let t;
try { t = JSON.parse(msg.payload.value); } catch (e) { node.warn('JSON 아님'); return null; }
const errs = [];
if (!t.tag) errs.push('tag 없음');
if (t.warn_value == null && t.alarm_value == null && t.low_warn == null && t.low_alarm == null) errs.push('기준값 없음');
if (t.warn_value != null && t.alarm_value != null && !(t.warn_value < t.alarm_value)) errs.push('warn ≥ alarm');
if (t.low_warn != null && t.low_alarm != null && !(t.low_warn > t.low_alarm)) errs.push('low_warn ≤ low_alarm');
if (errs.length) {
    node.status({ fill: 'red', shape: 'ring', text: `${t.tag} 거부: ${errs.join(', ')}` });
    return { payload: { ok: false, tag: t.tag, errors: errs } };
}
const th = flow.get('thresholds') || {};
th[t.tag] = t;
flow.set('thresholds', th);
const st = flow.get('stage') || {};
if (st[t.tag]) { Object.assign(st[t.tag], { c2: 0, c3: 0, cRel: 0, cLow3: 0 }); flow.set('stage', st); }
node.status({ fill: 'green', shape: 'dot', text: `${Object.keys(th).length}개 적용 · ${t.tag} #${t.threshold_id}` });
return { payload: { ok: true, applied: t } };

const iso = t => {
    if (typeof t === 'string' && /[+-]\d\d:\d\d$|Z$/.test(t)) return t;
    if (typeof t === 'string') return t.replace(' ', 'T') + '+09:00';
    const ms = t || (Date.now() + (flow.get('clockOffset') || 0));
    return new Date(ms + 9 * 3600e3).toISOString().replace(/\.\d+Z$/, '+09:00');
};
const s = msg.payload;
if (!s || !s.serial || s.value === undefined) return null;
const data = { tag: s.serial, ts: iso(s.ts), value: Number(s.value), quality: s.quality || 'GOOD' };
if (data.quality === 'GOOD') flow.set('clockOffset', Date.parse(data.ts) - Date.now());
const n = (context.get('n') || 0) + 1;
context.set('n', n);
node.status({ fill: 'green', shape: 'dot', text: `${n}건 · ${data.tag} ${data.value}` });
return { key: data.tag, payload: JSON.stringify(data) };

const iso = t => {
    if (typeof t === 'string' && /[+-]\d\d:\d\d$|Z$/.test(t)) return t;
    if (typeof t === 'string') return t.replace(' ', 'T') + '+09:00';
    const ms = t || (Date.now() + (flow.get('clockOffset') || 0));
    return new Date(ms + 9 * 3600e3).toISOString().replace(/\.\d+Z$/, '+09:00');
};
const DEFAULTS = {
    'AT-301': { warn_value: 15,  alarm_value: 30,  immediate_value: 200 },
    'AT-303': { warn_value: 15,  alarm_value: 30,  immediate_value: 200 },
    'IT-303': { low_warn: 17.85, low_alarm: 5.0 },
    'IT-307': { low_warn: 17.85, low_alarm: 5.0 },
    'TE-303': { warn_value: 190, alarm_value: 200 },
    'TE-305': { warn_value: 150, alarm_value: 160 }
};
const BASE = { threshold_id: null, warn_samples: 15, alarm_samples: 15, release_samples: 15, release_margin: 0 };
const PLC = { 'AT-301': 'D300', 'IT-303': 'D302', 'TE-303': 'D304', 'AT-303': 'D306', 'IT-307': 'D308', 'TE-305': 'D310' };
const NAME = { 1: '정상', 2: '주의', 3: '경고' };

const s = msg.payload;
const tag = s && s.serial;
const ths = flow.get('thresholds') || {};
if (!tag || (!ths[tag] && !DEFAULTS[tag])) return null;
const v = Number(s.value);
if (!Number.isFinite(v)) return null;
const t = { ...BASE, ...(DEFAULTS[tag] || {}), ...(ths[tag] || {}) };
const m = Number(t.release_margin) || 0;

let raw = 1, rule = 'HI', immediate = false;
if (t.alarm_value != null && v >= t.alarm_value) raw = 3;
else if (t.warn_value != null && v >= t.warn_value) raw = 2;
if (t.low_warn != null || t.low_alarm != null) {
    let lr = 1;
    if (t.low_alarm != null && v <= t.low_alarm) lr = 3;
    else if (t.low_warn != null && v <= t.low_warn) lr = 2;
    if (lr > raw || (t.warn_value == null && t.alarm_value == null)) { raw = Math.max(raw, lr); rule = 'LO'; }
}
if (t.immediate_value != null && v >= t.immediate_value) { raw = 3; immediate = true; rule = 'IMMEDIATE'; }
const released = (t.warn_value == null || v < t.warn_value - m) && (t.low_warn == null || v > t.low_warn + m);

const all = flow.get('stage') || {};
const cur = all[tag] || { stage: 1, c2: 0, c3: 0, cRel: 0, cLow3: 0 };
Object.assign(cur, { value: v, ts: iso(s.ts), type: s.type, seen: Date.now(), threshold_id: t.threshold_id });
cur.c2 = raw >= 2 ? cur.c2 + 1 : 0;
cur.c3 = raw >= 3 ? cur.c3 + 1 : 0;
cur.cRel = released ? cur.cRel + 1 : 0;
cur.cLow3 = raw < 3 ? cur.cLow3 + 1 : 0;
if (cur.stage >= 2) cur.peak = rule === 'LO' ? Math.min(cur.peak, v) : Math.max(cur.peak, v);

let ns = cur.stage;
if (immediate || cur.c3 >= t.alarm_samples) ns = 3;
else if (cur.stage === 1 && cur.c2 >= t.warn_samples) ns = 2;
else if (cur.stage >= 2 && cur.cRel >= t.release_samples) ns = 1;
else if (cur.stage === 3 && cur.cLow3 >= t.release_samples) ns = 2;

let ev = null;
if (ns !== cur.stage) {
    const prev = cur.stage;
    let phase;
    if (prev === 1) {
        phase = 'START';
        cur.edge_key = `P5-${tag}-${cur.ts.replace(/[-:]/g, '').slice(0, 15)}`;
        cur.max_stage = ns;
        cur.peak = v;
    } else if (ns === 1) phase = 'END';
    else { phase = 'UPDATE'; cur.max_stage = Math.max(cur.max_stage, ns); }
    cur.stage = ns;
    ev = { edge_key: cur.edge_key, phase, tag, threshold_id: cur.threshold_id, stage: ns, stage_name: NAME[ns],
           prev_stage: prev, max_stage: cur.max_stage, rule, reason: ns > prev ? '악화' : '완화·복귀',
           ts: cur.ts, value: v, plc: PLC[tag] || null };
    if (phase === 'END') { ev.peak_value = cur.peak; delete cur.edge_key; delete cur.max_stage; delete cur.peak; }
}
all[tag] = cur;
flow.set('stage', all);

const bad = Object.entries(all).filter(([, x]) => x.stage >= 2).map(([k, x]) => `${k} ${NAME[x.stage]}`);
node.status(bad.length ? { fill: 'red', shape: 'dot', text: bad.join(' · ') }
                       : { fill: 'green', shape: 'dot', text: `전체 정상 (${Object.keys(all).length}개)` });
if (!ev) return null;
return [{ payload: ev }, { payload: ev }];

const NAME = { 1: '정상', 2: '주의', 3: '경고' };
const th = flow.get('thresholds') || {};
const all = flow.get('stage') || {};
const now = Date.now();
const rows = {};
for (const [tag, c] of Object.entries(all).sort()) {
    rows[tag] = `${NAME[c.stage]} | 값 ${c.value} | 주의 연속 ${c.c2} · 경고 연속 ${c.c3} · 정상 연속 ${c.cRel}`
              + ` | 기준 ${th[tag] ? '#' + th[tag].threshold_id : '기본값'} | ${Math.round((now - c.seen) / 1000)}초 전 ${c.ts}`;
}
return { payload: rows };

msg.plcOk = !msg.error;
node.status(msg.plcOk ? { fill: 'green', shape: 'dot', text: `${msg.address} = [${msg.plcData}]` }
                      : { fill: 'red', shape: 'ring', text: `실패 ${msg.address}` });
return msg;

const e = msg.payload;
msg.ev = e;
if (!e.plc) return [null, msg];
msg.address = `${e.plc},2`;
msg.plcData = [e.stage, Math.round(e.value * 10)];
msg.payload = msg.plcData;
return [msg, null];

const e = msg.ev;
const data = {
    edge_key: e.edge_key, phase: e.phase, tag: e.tag, threshold_id: e.threshold_id,
    stage: e.stage, prev_stage: e.prev_stage, max_stage: e.max_stage, rule: e.rule, reason: e.reason,
    ts: e.ts, value: e.value, ...(e.phase === 'END' ? { peak_value: e.peak_value } : {}),
    plc_address: msg.address || null, plc_written: msg.plcData || null, plc_ok: msg.plcOk ?? null
};
node.status({ fill: e.phase === 'END' ? 'green' : 'red', shape: 'dot', text: `${e.phase} ${e.tag} ${e.stage_name}` });
return { key: e.tag, payload: JSON.stringify(data) };

const iso = t => {
    if (typeof t === 'string' && /[+-]\d\d:\d\d$|Z$/.test(t)) return t;
    if (typeof t === 'string') return t.replace(' ', 'T') + '+09:00';
    const ms = t || (Date.now() + (flow.get('clockOffset') || 0));
    return new Date(ms + 9 * 3600e3).toISOString().replace(/\.\d+Z$/, '+09:00');
};
// equipment_id(중앙 서버 시드) 또는 equipment_code 로 인버터 연결 설비를 찾음
const INVERTERS = { 36: { code: 'ED-FAN', name: '전착 건조로 배기팬', min: 20, max: 60 } };
let c;
try { c = JSON.parse(msg.payload.value); } catch (e) { node.warn('JSON 아님'); return null; }
const now = Date.now() + (flow.get('clockOffset') || 0);
const reply = (result, message) => [null, { payload: { command_id: c.command_id, equipment_id: c.equipment_id,
    command: c.command, value: c.value, source: c.source, result, completed_at: iso(), detail: { message } } }];

const done = flow.get('cmdDone') || [];
if (done.includes(c.command_id)) return reply('DUPLICATE', '이미 처리한 명령');
done.push(c.command_id);
flow.set('cmdDone', done.slice(-200));
if (c.expires_at && Date.parse(c.expires_at) < now) return reply('EXPIRED', `만료 ${c.expires_at}`);
const inv = INVERTERS[c.equipment_id] || Object.values(INVERTERS).find(v => v.code === c.equipment_code);
if (!inv) return reply('REJECTED', `equipment_id ${c.equipment_id} 인버터 없음`);
if (c.command === 'FAN_HZ' && !(Number(c.value) >= inv.min && Number(c.value) <= inv.max))
    return reply('REJECTED', `범위 밖 ${c.value}Hz`);
if (c.command !== 'FAN_HZ' && c.command !== 'FAN_STOP') return reply('REJECTED', `지원하지 않는 명령 ${c.command}`);
node.status({ fill: 'blue', shape: 'dot', text: `#${c.command_id} ${c.command} ${c.value ?? ''} (${c.source || 'USER'})` });
return [{ cmd: c }, null];

const c = msg.cmd;
const stop = c.command === 'FAN_STOP';
const hz = stop ? 0 : Number(c.value);
const motor = flow.get('motor') || {};
motor[c.equipment_id] = { hz, source: c.source, at: Date.now() };
flow.set('motor', motor);
const info = { ...c, target_hz: hz };
node.status({ fill: stop ? 'grey' : 'blue', shape: 'dot', text: `설비 ${c.equipment_id} → ${stop ? '정지' : hz + 'Hz'} (${c.source || 'USER'})` });
if (stop) return [null, { payload: [5057], cmd: info }];
return [{ payload: [Math.round(hz * 100)], cmd: info }, { payload: [5058], cmd: info }];

const motor = flow.get('motor') || {};
for (const k of Object.keys(motor)) motor[k].hz = 0;
flow.set('motor', motor);
node.status({ fill: 'red', shape: 'dot', text: '현장 정지 ' + new Date().toLocaleTimeString() });
return { payload: [5057] };

const d = msg.payload;
const c = msg.cmd || {};
const base = { command_id: c.command_id ?? null, equipment_id: c.equipment_id, command: c.command,
               value: c.value, source: c.source };
if (!Array.isArray(d) || d.length < 6) {
    node.status({ fill: 'red', shape: 'ring', text: '읽기 실패' });
    return c.equipment_id == null ? null : { payload: { ...base, result: 'FAILED', detail: { message: '인버터 읽기 실패' } } };
}
const s = { cmd_hz: d[0] / 100, run_cmd: d[1], output_hz: d[5] / 100, current_a: d[4] / 10 };
if (c.equipment_id == null) {
    node.status({ fill: 'grey', shape: 'dot', text: `현재 ${s.output_hz}Hz / ${s.current_a}A` });
    return null;
}
let ok, result, message;
if (c.target_hz === 0) {
    ok = s.output_hz === 0;
    result = ok || s.run_cmd === 5057 ? 'DONE' : 'FAILED';
    message = ok ? '정지 완료' : result === 'DONE' ? `감속 정지 중 ${s.output_hz}Hz` : '정지 안 됨';
} else {
    ok = Math.abs(s.output_hz - c.target_hz) < 0.5;
    result = ok || (s.cmd_hz === c.target_hz && s.output_hz > 0) ? 'DONE' : 'FAILED';
    message = ok ? `${c.target_hz}Hz 도달` : result === 'DONE' ? `변속 중 ${s.output_hz} → ${c.target_hz}Hz` : `지령 불일치 (${s.cmd_hz}Hz)`;
}
node.status({ fill: ok ? 'green' : result === 'DONE' ? 'yellow' : 'red', shape: 'dot', text: `${c.source || 'USER'} ${message}` });
return { payload: { ...base, result, detail: { target_hz: c.target_hz, ...s, fan_rpm: Math.round(s.output_hz * 30), message } } };

