const iso = t => {
    if (typeof t === 'string' && /[+-]\d\d:\d\d$|Z$/.test(t)) return t;
    if (typeof t === 'string') return t.replace(' ', 'T') + '+09:00';
    const ms = t || (Date.now() + (flow.get('clockOffset') || 0));
    return new Date(ms + 9 * 3600e3).toISOString().replace(/\.\d+Z$/, '+09:00');
};
const TIMEOUT_MS = 10000;
const all = flow.get('stage') || {};
const lost = flow.get('commLost') || {};
const now = Date.now();
const out = [];
for (const [tag, cur] of Object.entries(all)) {
    const isLost = now - cur.seen > TIMEOUT_MS;
    if (isLost && !lost[tag]) {
        lost[tag] = now;
        out.push({ key: tag, payload: JSON.stringify({ tag, ts: iso(), value: cur.value, quality: 'COMM_LOST' }) });
    } else if (!isLost && lost[tag]) delete lost[tag];
}
flow.set('commLost', lost);
const n = Object.keys(lost).length;
node.status(n ? { fill: 'red', shape: 'dot', text: `끊김 ${n}개: ${Object.keys(lost).join(', ')}` }
              : { fill: 'green', shape: 'ring', text: `정상 수신 ${Object.keys(all).length}개` });
return [out];
